<?php
require __DIR__.'/app/bootstrap.php';$u=require_user();require_commerce();$item=one('SELECT i.*,o.customer_id,o.seller_id,o.shop_name,o.status order_status FROM order_items i JOIN orders o ON o.id=i.order_id WHERE i.id=? AND o.customer_id=?',[(int)param('item'),$u['id']]);if(!$item)fail(404,t('Order item not found.'));
if($item['order_status']!=='completed')fail(403,t('You can review this food after the order is collected or delivered.'));
if((int)$item['seller_id']===(int)$u['id']||$u['role']==='admin')fail(403,t('Seller and administrator accounts cannot review their own transactions.'));
$review=one('SELECT * FROM product_reviews WHERE user_id=? AND product_key=?',[$u['id'],$item['product_key']]);$err=[];
if(post()){$rating=val('rating');$text=val('review_text');if(!in_array($rating,['1','2','3','4','5'],true))$err[]=t('Choose between 1 and 5 stars.');if(!text_valid($text,0,2000))$err[]=t('Keep your review under 2000 characters.');
 if(!limit('product-review',15,3600))$err[]=t('Too many review changes. Please try again later.');
 if(!$err){db()->beginTransaction();q('UPDATE users SET full_name=full_name WHERE id=?',[$u['id']]);$latest=one('SELECT id FROM product_reviews WHERE user_id=? AND product_key=?',[$u['id'],$item['product_key']]);
  if($latest)q('UPDATE product_reviews SET rating=?,review_text=?,updated_at=? WHERE id=? AND user_id=?',[(int)$rating,$text,now(),$latest['id'],$u['id']]);
  else q('INSERT INTO product_reviews (user_id,seller_id,product_id,product_key,order_item_id,product_name,shop_name,rating,review_text,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)',[$u['id'],$item['seller_id'],$item['product_id'],$item['product_key'],$item['id'],$item['name'],$item['shop_name'],(int)$rating,$text,now(),now()]);
  if(experience_ready()){dismiss_order_prompt((int)$item['order_id'],(int)$u['id']);notify_review((int)$item['seller_id'],(int)$item['order_id'],t('Food review received'),$item['name'].' · '.$rating.' stars','seller/order.php?id='.$item['order_id']);}db()->commit();flash(t('Your food review has been saved.'));go('reviews.php');
 }
}
$title=$review?t('Edit food review'):t('Review your food');require ROOT.'/app/header.php'; ?>
<main class="page narrow" id="main"><section class="auth-card"><span class="heading-kicker"><?=e(t('YOUR EXPERIENCE MATTERS'))?></span><h1><?=e($item['name'])?></h1><p><?=e(t('From'))?> <?=e($item['shop_name'])?></p><span class="chip"><?=e(t('Verified order'))?></span><?php errors($err); ?><form method="post"><?=csrf()?><fieldset class="rating-picker"><legend><?=e(t('Your rating'))?></legend><?php for($i=1;$i<=5;$i++): ?><label><input type="radio" name="rating" value="<?=$i?>" required <?=($_SERVER['REQUEST_METHOD']==='POST'?val('rating'):($review['rating']??''))==$i?'checked':''?>><span><?=$i?> ★</span></label><?php endfor ?></fieldset><?php area('review_text',t('Your review (optional)'),$_SERVER['REQUEST_METHOD']==='POST'?val('review_text'):($review['review_text']??''),'maxlength="2000"'); ?><p class="hint"><?=e(t('Your name and review will be public. Reviews stay on the seller’s profile even if a dish is removed.'))?></p><button class="pill primary wide space-top"><?=e(t('Save Review'))?></button></form></section></main><?php require ROOT.'/app/footer.php'; ?>
